<?php
declare(strict_types=1);

/**
 * 2.38.3 Corrections to the built-in compliance content, applied by migration 102 through Align\Compliance\Corrections
 * (see that class for the format and the rules). Generated from the content Align shipped before 2.38.3: each "set" pair
 * is [shipped text, corrected text], so only fields an MSP has not edited change; edited ones are offered to an admin.
 * Sources: eCFR (45 CFR 164, 16 CFR 314, 32 CFR 170), FAR 52.204-21, NIST SP 800-171 r2 / CSF 2.0, PCI DSS v4.0.1,
 * ISO/IEC 27001:2022, AICPA TSC 2017 (rev. 2022), CIS Controls v8.1, CISA ScubaGear v2.0 baselines, Cal. Civ. Code and 11 CCR.
 */
return [
    ['fw' => 'hipaa-security', 'framework' => ['description' => ['Standards and implementation specifications from 45 CFR 164.308, 164.310 and 164.312, summarized. (R) = required, (A) = addressable. HHS has proposed updates to the Security Rule, so check for changes. This checklist is not legal advice.', 'Applies to HIPAA covered entities (health plans, health care clearinghouses and health care providers that conduct standard electronic transactions) and their business associates, including MSPs that create, receive, maintain or transmit ePHI. Summarizes the standards and implementation specifications of the Security Rule as currently in force: 45 CFR 164.308 (administrative), 164.310 (physical), 164.312 (technical), 164.314 (organizational) and 164.316 (policies, procedures and documentation). (R) = required; (A) = addressable, which is not optional: implement it, use an equivalent alternative, or document why neither is reasonable and appropriate (164.306(d)(3)). HHS proposed an overhaul of the Security Rule in January 2025 (90 FR 898) that would remove the addressable category and make measures such as encryption and MFA mandatory; it is a proposal, not a current requirement, until HHS publishes a final rule. This checklist is a summary, not legal advice.']], 'why' => 'Scope: covered entities and business associates; 164.314 and 164.316 added; addressable explained; the Jan 2025 proposed rule is not final.'],
    ['fw' => 'hipaa-security', 'insert' => ['Administrative safeguards', '164.308(a)(4)(ii)(A)', 'Isolating health care clearinghouse functions (R)', 'Applies only if the organization includes a health care clearinghouse; mark N/A otherwise. Evidence: how clearinghouse ePHI is kept separate from the rest of the organization.', null, 'net_segmentation,iam_least_privilege'], 'after' => '164.308(a)(3)(ii)(C)', 'why' => '164.308(a)(4)(ii)(A) was the only Appendix A implementation specification missing.'],
    ['fw' => 'hipaa-security', 'ref' => '164.308(b)(1)', 'set' => ['ref' => ['164.308(b)(1)', '164.308(b)(1)-(3)'], 'title' => ['Business associate agreements in place (R)', 'Written contract or other arrangement with each business associate that meets 164.314(a) (R)'], 'guidance' => ['Including with the MSP and cloud vendors that handle ePHI.', 'Including the MSP and cloud vendors that create, receive, maintain or transmit ePHI. A business associate must also get one from each subcontractor that handles ePHI (164.308(b)(2)).']], 'why' => 'The required implementation specification is 164.308(b)(3) (a written contract meeting 164.314(a)); the subcontractor flow-down is 164.308(b)(2).'],
    ['fw' => 'hipaa-security', 'ref' => '164.310(d)(2)(iii)', 'set' => ['auto_check' => ['hw_lifecycle', null]], 'why' => 'Hardware lifecycle status says nothing about recording hardware and media movements.'],
    ['fw' => 'hipaa-security', 'ref' => '164.312(a)(2)(iv)', 'set' => ['title' => ['Encryption and decryption of ePHI at rest (A)', 'Encryption and decryption: a mechanism to encrypt and decrypt ePHI (A)']], 'why' => 'The specification does not say "at rest".'],
    ['fw' => 'hipaa-security', 'ref' => '164.312(e)(2)(ii)', 'set' => ['tags' => ['net_encrypt_transit,email_filter', 'net_encrypt_transit']], 'why' => 'Email filtering is not transmission encryption.'],
    ['fw' => 'hipaa-security', 'insert' => ['Organizational requirements', '164.314(a)', 'Business associate contracts include the required Security Rule terms (R)', 'The contract requires the business associate to comply with the Security Rule, to make its subcontractors agree to the same terms, and to report security incidents, including breaches of unsecured PHI (164.410). Evidence: the BAA checklist per vendor (HIPAA BAA checklist template). 164.314(b) (group health plans) is N/A for most clients.', null, 'vendor_contracts'], 'after' => '164.312(e)(2)(ii)', 'why' => '164.314(a) is a required standard: what a business associate contract must contain.'],
    ['fw' => 'hipaa-security', 'insert' => ['Policies, procedures and documentation', '164.316(a)', 'Policies and procedures (R): reasonable and appropriate written policies and procedures to comply with each standard and implementation specification', 'Policies may be changed at any time as long as the changes are documented and implemented. Evidence: the approved policy set (a policy or procedure for each standard) with owner and approval date.', null, 'gov_policy'], 'after' => '164.314(a)', 'why' => '164.316 is a required standard of the Security Rule and was missing.'],
    ['fw' => 'hipaa-security', 'insert' => ['Policies, procedures and documentation', '164.316(b)(1)', 'Documentation (R): policies, procedures and any required action, activity or assessment are kept in written (which may be electronic) form', 'Includes the risk analysis, evaluations, incident records, decisions on addressable specifications (164.306(d)(3)) and business associate contracts. Evidence: the document library showing each record and its date.', null, 'gov_policy,data_retention_disposal'], 'after' => '164.316(a)', 'why' => '164.316(b)(1) is a required standard and was missing.'],
    ['fw' => 'hipaa-security', 'insert' => ['Policies, procedures and documentation', '164.316(b)(2)(i)', 'Time limit (R): required documentation is kept for 6 years from when it was created or last in effect, whichever is later', 'Evidence: retention setting or schedule covering security policies, risk analyses, evaluations and incident records, with superseded versions kept.', null, 'data_retention_disposal,gov_policy'], 'after' => '164.316(b)(1)', 'why' => 'Required implementation specification, missing.'],
    ['fw' => 'hipaa-security', 'insert' => ['Policies, procedures and documentation', '164.316(b)(2)(ii)', 'Availability (R): documentation is available to the people responsible for carrying out the procedures it covers', 'Evidence: where the policy library lives and who can reach it.', null, 'gov_policy'], 'after' => '164.316(b)(2)(i)', 'why' => 'Required implementation specification, missing.'],
    ['fw' => 'hipaa-security', 'insert' => ['Policies, procedures and documentation', '164.316(b)(2)(iii)', 'Updates (R): documentation is reviewed periodically and updated as needed after environmental or operational changes affecting the security of ePHI', 'Evidence: review log with dates and the changes made.', null, 'gov_review,gov_policy'], 'after' => '164.316(b)(2)(ii)', 'why' => 'Required implementation specification, missing.'],
    ['fw' => 'wisp-ftc', 'framework' => ['description' => ['Written Information Security Program elements required by the FTC Safeguards Rule (16 CFR 314.4) for "financial institutions" such as tax preparers, CPAs, mortgage brokers, auto dealers and lenders. IRS Publication 5708 provides a WISP template for tax professionals. Institutions with fewer than 5,000 consumers are exempt from some elements (314.6: written risk assessment, continuous monitoring/pen testing, written IR plan, annual report); mark those N/A if that applies. This checklist summarizes the rule and is not legal advice.', 'Written Information Security Program elements required by the FTC Safeguards Rule (16 CFR Part 314) for "financial institutions" such as tax preparers, CPAs, mortgage brokers, auto dealers and lenders. IRS Publication 5708 provides a WISP template for tax professionals. Institutions that maintain customer information on fewer than 5,000 consumers are exempt from 314.4(b)(1) (the risk assessment must still be done but need not be written), (d)(2) (continuous monitoring, or annual penetration testing and vulnerability assessments every six months), (h) (written incident response plan) and (i) (annual written report to the board); mark those N/A if that applies. The FTC notification requirement (314.4(j), effective May 13, 2024) applies regardless of size. This checklist summarizes the rule and is not legal advice.']], 'why' => 'Names the exact paragraphs 314.6 exempts and the 2024 notification amendment, which has no size exemption.'],
    ['fw' => 'wisp-ftc', 'ref' => 'WISP', 'set' => ['ref' => ['WISP', '314.3(a)']], 'why' => '"WISP" is not a reference; the written-program duty is 314.3(a).'],
    ['fw' => 'wisp-ftc', 'ref' => '314.4(b)', 'set' => ['ref' => ['314.4(b)', '314.4(b)(1)'], 'guidance' => ['Include criteria for evaluating and categorizing risks, assessing the security of systems and information, and how risks will be mitigated or accepted.', 'Include criteria for evaluating and categorizing risks, assessing the security of systems and information, and how risks will be mitigated or accepted. Exempt from the written form (not from doing the assessment) with fewer than 5,000 consumers (314.6).']], 'why' => 'The written assessment is 314.4(b)(1), the paragraph 314.6 exempts; the assessment itself is still required.'],
    ['fw' => 'wisp-ftc', 'ref' => '314.4(c)(4)', 'set' => ['guidance' => ['Mark N/A if the firm does not develop or host its own applications.', 'The secure-development part applies only to applications the firm develops in-house. The second part applies to everyone: a procedure to evaluate, assess or test the security of externally developed applications (for example tax, accounting or CRM software) used to transmit, access or store customer information. Evidence: application security review records.']], 'why' => 'The second half of (c)(4), evaluating externally developed applications, applies to every institution.'],
    ['fw' => 'wisp-ftc', 'ref' => '314.4(e)(2)', 'set' => ['ref' => ['314.4(e)(2)', '314.4(e)(2)-(4)'], 'title' => ['Qualified information security personnel (employees or a service provider) manage the program and keep their knowledge current', 'Qualified information security personnel (employees, an affiliate or a service provider) manage the program, receive security updates and training, and are verified to keep their knowledge of threats current']], 'why' => 'Security updates and training are (e)(3); verifying personnel stay current is (e)(4).'],
    ['fw' => 'wisp-ftc', 'ref' => '314.4(j)', 'set' => ['guidance' => ['A notification event is unauthorized acquisition of unencrypted customer information.', 'A notification event is acquisition of unencrypted customer information without the consumer\'s authorization; information counts as unencrypted if the encryption key was also accessed, and unauthorized access is presumed to be acquisition unless there is reliable evidence otherwise. Notify the FTC through its online form as soon as possible and no later than 30 days after discovery (the first day any employee, officer or agent knows of it). The 314.6 small-institution exemption does not apply.']], 'why' => 'Adds the key-access rule, the presumption of acquisition, the discovery date and that 314.6 does not exempt (j).'],
    ['fw' => 'ccpa-cpra', 'ref' => '1798.120', 'set' => ['guidance' => ['Per §7026, stop selling/sharing and notify third parties who received the data; real-time bidding opt-outs must be honored immediately where feasible. Mark N/A if no sale or sharing.', 'Per §7026(f), stop selling/sharing as soon as feasibly possible and no later than 15 business days, and notify the third parties the personal information was sold or shared with after the request and before compliance, directing them to comply. Mark N/A if no sale or sharing.']], 'why' => 'Section 7026(f): no "immediately" rule for real-time bidding; the deadline is 15 business days.'],
    ['fw' => 'ccpa-cpra', 'insert' => ['Consumer requests', '1798.120(c)', 'Personal information of consumers known to be under 16 is not sold or shared without opt-in consent (the consumer if 13-15, a parent or guardian if under 13)', 'Willful disregard of age counts as actual knowledge. See §§7070-7072 for opt-in and parental consent. Mark N/A with a reason if the business does not sell or share personal information or does not knowingly collect it from minors.', null, 'gov_privacy_notice'], 'after' => '1798.120', 'why' => 'A separate statutory duty the privacy notice template covers but the checklist did not.'],
    ['fw' => 'ccpa-cpra', 'ref' => '1798.82', 'set' => ['guidance' => ['SB 446 deadlines apply from Jan. 1, 2026 (delay allowed for law enforcement needs or to determine scope). Notices use the required "Notice of Data Breach" headings. Evidence: IR plan section and notice template.', 'SB 446 deadlines apply from Jan. 1, 2026 (delay allowed for the legitimate needs of law enforcement, or as needed to determine the scope of the breach and restore the system). 1798.82 applies to any person or business that owns or licenses computerized personal information of California residents, even when the CCPA thresholds are not met; a business that only maintains the data notifies the owner immediately after discovery. Notices use the required "Notice of Data Breach" headings. Evidence: IR plan section and notice template.']], 'why' => '1798.82 applies to any business holding California residents\' computerized personal information, even below the CCPA thresholds.'],
    ['fw' => 'cmmc-l1', 'framework' => ['description' => ['Applies to defense contractors and subcontractors that process, store or transmit Federal Contract Information (FCI) but not CUI. Passing means all 15 FAR 52.204-21(b)(1) basic safeguarding requirements are MET (no POA&Ms or partial credit allowed), confirmed by an annual self-assessment entered in SPRS together with an annual affirmation by a senior company official (32 CFR 170.15). CMMC phase-in began Nov 10, 2025 (Phase 1: self-assessments in solicitations); Phase 2 starts Nov 10, 2026. Based on FAR 52.204-21 (Nov 2021) and the 32 CFR Part 170 final rule. This is a summary for tracking an assessment, not legal advice.', 'Applies to defense contractors and subcontractors that process, store or transmit Federal Contract Information (FCI) but not CUI. Passing means all 15 FAR 52.204-21(b)(1) basic safeguarding requirements are MET (no POA&Ms or partial credit allowed), confirmed by an annual self-assessment entered in SPRS together with an annual affirmation by a senior company official (32 CFR 170.15). Level 1 status is self-assessment only; it must be current before award and kept current during the contract. CMMC phase-in began Nov 10, 2025, when DFARS 252.204-7021 took effect (Phase 1: self-assessments in solicitations); Phase 2 began Nov 10, 2026. Based on FAR 52.204-21 (Nov 2021), 32 CFR Part 170 and DFARS 252.204-7021. This is a summary for tracking an assessment, not legal advice.']], 'why' => 'Phase 2 has begun; names the DFARS clause that puts CMMC in contracts.'],
    ['fw' => 'cmmc-l2', 'framework' => ['description' => ['Applies to defense contractors and subcontractors that process, store or transmit Controlled Unclassified Information (CUI). Covers all 110 security requirements of NIST SP 800-171 Rev 2, the same list DFARS 252.204-7012 already requires. Final status requires all 110 MET; Conditional status requires a score of at least 88 of 110 (SPRS-style, DoD Assessment Methodology) with only eligible 1-point items on a POA&M, closed out within 180 days. Status is by self-assessment or C3PAO certification (as the contract specifies) every 3 years, plus an annual affirmation in SPRS by a senior official. CMMC phase-in began Nov 10, 2025; Phase 2 (Nov 10, 2026) makes Level 2 C3PAO certification a condition of award where the solicitation requires it. Based on NIST SP 800-171 r2 (Feb 2020), SP 800-171A (June 2018) and 32 CFR Part 170. This is a summary for tracking an assessment, not legal advice.', 'Applies to defense contractors and subcontractors that process, store or transmit Controlled Unclassified Information (CUI). Covers all 110 security requirements of NIST SP 800-171 Rev 2, the same list DFARS 252.204-7012 already requires. Final status requires all 110 MET; Conditional status requires a score of at least 88 (DoD Assessment Methodology values, 110 maximum) with only eligible 1-point items, plus SC.L2-3.13.11 when encryption is used but not FIPS-validated, on a POA&M, closed out within 180 days (32 CFR 170.21). Status is by self-assessment or C3PAO certification (as the contract specifies) every 3 years, with an affirmation in SPRS by a senior official at each status and annually (170.22). DFARS 252.204-7021 (effective Nov 10, 2025) phases CMMC into contracts: Phase 1 from Nov 10, 2025 (self-assessments); Phase 2 from Nov 10, 2026 (Level 2 C3PAO certification where the solicitation requires it); Phase 3 from Nov 10, 2027; full implementation from Nov 10, 2028. Based on NIST SP 800-171 r2 (Feb 2020), SP 800-171A (June 2018) and 32 CFR Part 170. This is a summary for tracking an assessment, not legal advice.']], 'why' => 'Adds the 3.13.11 exception, affirmations at each status (170.22), the DFARS rule and the phase dates.'],
    ['fw' => 'cmmc-l1', 'ref' => 'SC.L1-b.1.x', 'set' => ['guidance' => ['A managed firewall defines the external boundary and key internal boundaries, with rules that deny by default and are reviewed. Evidence: network diagram, firewall rule export, firewall logs. NIST SP 800-171 r2: 3.13.1.', 'A managed firewall defines the external boundary and key internal boundaries, and traffic crossing them is monitored and controlled (for example unneeded inbound connections blocked and rules reviewed). Evidence: network diagram, firewall rule export, firewall logs. NIST SP 800-171 r2: 3.13.1.']], 'why' => 'Deny-by-default is 3.13.6, a Level 2 requirement; Level 1 asks to monitor and control boundary traffic.'],
    ['fw' => 'cmmc-l2', 'ref' => 'RA.L2-3.11.1', 'set' => ['title' => ['Periodically assess the risk to organizational operations (including mission, functions, image, or reputation), organizational assets, and individuals, resulting from the operation of organizational systems and the associated processing, storage, or…', 'Periodically assess the risk to organizational operations, organizational assets, and individuals, resulting from the operation of organizational systems and the associated processing, storage, or transmission of CUI.'], 'guidance' => ['Objectives: risk assessment frequency is defined and risk assessments are performed. Evidence: dated risk assessment report and risk register. SPRS: 3 pts; cannot be on a POA&M.', 'Operations include mission, functions, image and reputation. Objectives: risk assessment frequency is defined and risk assessments are performed. Evidence: dated risk assessment report and risk register. SPRS: 3 pts; cannot be on a POA&M.']], 'why' => 'The NIST text is longer than the title column, so "transmission of CUI" was cut off.'],
    ['fw' => 'cmmc-l2', 'ref' => 'SC.L2-3.13.11', 'set' => ['guidance' => ['Objectives: cryptography protecting CUI uses FIPS 140-validated modules. Evidence: CMVP certificate numbers for encryption products, FIPS mode settings. SPRS: 5 pts, or 3 if encryption is used but not FIPS-validated; only that partial case may be on a POA&M.', 'Objectives: cryptography protecting CUI uses FIPS 140-validated modules (FIPS 140-3 for new purchases; NIST moved FIPS 140-2 certificates to its Historical list on Sept 21, 2026, so record any 140-2 module still in use and plan its replacement). Evidence: CMVP certificate numbers for encryption products, FIPS mode settings. SPRS: 5 pts, or 3 if encryption is used but not FIPS-validated; only that partial case may be on a POA&M.']], 'why' => 'FIPS 140-2 certificates moved to the CMVP Historical list on Sept 21, 2026.'],
    ['fw' => 'pci-dss-4', 'framework' => ['description' => ['Applies to any business that stores, processes or transmits payment card data, or that can affect the security of that data (for example, an MSP managing a merchant\'s card environment). Most small merchants validate each year with a Self-Assessment Questionnaire (SAQ A, A-EP, B, B-IP, C, C-VT, P2PE or D) chosen by how they take cards; each SAQ covers only a subset of these requirements, so mark the rest N/A with a short reason. Passing means every applicable requirement is in place, documented and signed off in the SAQ or Report on Compliance and Attestation of Compliance. Based on PCI DSS v4.0.1 (June 2024), the current version; v3.2.1 was retired on March 31, 2024, and the v4.0 future-dated requirements became mandatory on March 31, 2025. Controls are plain-language summaries for tracking, not the PCI SSC text and not legal advice.', 'Applies to any business that stores, processes or transmits payment card data, or that can affect the security of that data (for example, an MSP managing a merchant\'s card environment). Most small merchants validate each year with a Self-Assessment Questionnaire (SAQ A, A-EP, B, B-IP, C, C-VT, P2PE, SPoC or D) chosen by how they take cards; each SAQ covers only a subset of these requirements, so mark the rest N/A with a short reason. Passing means every applicable requirement is in place, documented and signed off in the SAQ or Report on Compliance and Attestation of Compliance. Based on PCI DSS v4.0.1 (June 2024), the only active version: v3.2.1 was retired on March 31, 2024 and v4.0 on December 31, 2024, and the v4.0 future-dated requirements have been mandatory since March 31, 2025. Appendix A1 applies to multi-tenant service providers and A2 to card-present terminals using SSL/early TLS; Appendix A3 (designated entities) applies only when a card brand or acquirer requires it and is not listed. Controls are plain-language summaries for tracking, not the PCI SSC text and not legal advice.']], 'why' => 'v4.0 retirement date, SAQ SPoC, and the appendices that apply.'],
    ['fw' => 'pci-dss-4', 'ref' => '1.2.1', 'set' => ['title' => ['Configuration standards for firewall and router rulesets are defined, implemented and maintained', 'Firewall, router and other network security control rulesets follow a written configuration standard that is applied and kept up to date']], 'why' => 'Too close to the PCI wording; also covers cloud and virtual network controls.'],
    ['fw' => 'pci-dss-4', 'ref' => '2.2.7', 'set' => ['title' => ['All remote admin access to systems is encrypted with strong cryptography', 'All non-console administrative access is encrypted with strong cryptography']], 'why' => 'Covers all non-console admin access, including from inside the network.'],
    ['fw' => 'pci-dss-4', 'ref' => '3.4.1', 'set' => ['title' => ['Card numbers are masked on screen so only people with a need see more than the first six/last four digits', 'Card numbers are masked when displayed so only people with a business need see more than the BIN and last four digits']], 'why' => 'v4.0.1 replaced "first six and last four" with "the BIN and last four".'],
    ['fw' => 'pci-dss-4', 'ref' => '5.3.3', 'set' => ['title' => ['Removable media is scanned automatically when inserted or mounted', 'Removable media is scanned automatically when inserted, connected or mounted, or continuously behavior-monitored while in use']], 'why' => 'Continuous behavioral analysis is an accepted alternative.'],
    ['fw' => 'pci-dss-4', 'ref' => '6.3.3', 'set' => ['auto_check' => ['os_supported', null]], 'why' => 'A supported OS does not show critical patches went on within a month.'],
    ['fw' => 'pci-dss-4', 'ref' => '6.4.3', 'set' => ['guidance' => ['Evidence: script inventory with justification, approval and integrity controls (CSP, SRI or monitoring tool). Was future-dated; required since March 31, 2025.', 'Evidence: inventory of every script on payment pages (including the merchant page that embeds a processor\'s payment iframe) with justification, approval and integrity controls (CSP, SRI or monitoring tool). Was future-dated; required since March 31, 2025. Since January 2025, SAQ A merchants no longer answer 6.4.3 and 11.6.1 but must confirm their site is not susceptible to script attacks.']], 'why' => 'v4.0.1 applicability notes and the January 2025 SAQ A change.'],
    ['fw' => 'pci-dss-4', 'ref' => '8.4.2', 'set' => ['title' => ['MFA is required for all access into the CDE', 'MFA is required for all non-console access into the CDE'], 'guidance' => ['Evidence: Conditional Access or equivalent enforcing MFA for every user reaching CDE systems. Was future-dated; required since March 31, 2025.', 'Evidence: Conditional Access or equivalent enforcing MFA for every non-console login to CDE systems. Accounts that sign in only with phishing-resistant factors (for example FIDO2 keys or passkeys) need no separate MFA. Was future-dated; required since March 31, 2025.']], 'why' => 'Non-console access only; v4.0.1 exempts accounts that sign in only with phishing-resistant factors.'],
    ['fw' => 'pci-dss-4', 'ref' => '11.6.1', 'set' => ['title' => ['Payment pages are monitored for unauthorized changes to content and headers, checked at least weekly', 'Payment pages are monitored for unauthorized changes to their scripts and security-relevant HTTP headers, at least weekly or as a targeted risk analysis sets']], 'why' => 'v4.0.1 narrowed it to scripts and security-impacting headers; frequency may come from a targeted risk analysis.'],
    ['fw' => 'pci-dss-4', 'ref' => '12.3.1', 'set' => ['title' => ['A targeted risk analysis is done for each requirement that lets the entity pick how often to do it', 'A written targeted risk analysis, reviewed at least yearly, supports each requirement that calls for one'], 'guidance' => ['Evidence: targeted risk analyses for flexible-frequency requirements, reviewed yearly. Was future-dated; required since March 31, 2025.', 'Evidence: targeted risk analyses for each requirement that asks for one (such as those letting the entity set how often a task is done), reviewed yearly. Was future-dated; required since March 31, 2025.']], 'why' => 'v4.0.1 wording: each requirement that calls for a targeted risk analysis.'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.1.1', 'Multi-tenant providers keep their own environment and each customer\'s logically separate, with no access between them without authorization', 'Evidence: architecture and access settings showing provider and customer environments separated, with authorized access only. Multi-tenant service providers only.', null, 'net_segmentation,cloud_config'], 'after' => '12.10.7', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.1.2', 'Each customer can reach only its own card data and cardholder data environment', 'Evidence: tenant isolation settings and access tests showing one customer cannot see another\'s data. Multi-tenant service providers only.', null, 'iam_least_privilege,net_segmentation'], 'after' => 'A1.1.1', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.1.3', 'Each customer can use only the system resources allocated to it', 'Evidence: per-tenant resource limits (CPU, memory, storage, bandwidth). Multi-tenant service providers only.', null, 'net_segmentation,cloud_config'], 'after' => 'A1.1.2', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.1.4', 'Penetration tests confirm tenant separation works, at least every six months', 'Evidence: six-monthly penetration test reports covering separation between tenants. Was future-dated; required since March 31, 2025. Multi-tenant service providers only.', null, 'vuln_pentest,net_segmentation'], 'after' => 'A1.1.3', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.2.1', 'Audit logging is available for each customer\'s environment as Requirement 10 asks, and each customer sees only its own logs', 'Evidence: per-tenant logging on by default, log locations given to customers, access limited to the owning customer. Multi-tenant service providers only.', null, 'log_collect,log_protect'], 'after' => 'A1.1.4', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.2.2', 'Processes support prompt forensic investigation of a suspected or confirmed incident at any customer', 'Evidence: documented forensic support procedure and the ability to preserve a tenant\'s logs and images. Multi-tenant service providers only.', null, 'ir_plan'], 'after' => 'A1.2.1', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'pci-dss-4', 'insert' => ['Appendix A1 — Multi-tenant service providers', 'A1.2.3', 'Customers can securely report suspected incidents and vulnerabilities, which the provider investigates and fixes', 'Evidence: published secure reporting channel and records of customer reports handled. Was future-dated; required since March 31, 2025. Multi-tenant service providers only.', null, 'ir_reporting,vuln_remediation'], 'after' => 'A1.2.2', 'why' => 'Appendix A1 is required for multi-tenant service providers (many MSPs that host customer environments).'],
    ['fw' => 'iso-27001-2022', 'ref' => 'Clause 8.2', 'set' => ['guidance' => ['Risk assessments repeated at least annually and after major changes. Evidence: dated risk assessment results.', 'Risk assessments repeated at the planned intervals set in the methodology (most organizations choose yearly) and whenever significant changes are proposed or happen. Evidence: dated risk assessment results.']], 'why' => 'Clause 8.2 sets planned intervals and significant changes, not an annual minimum.'],
    ['fw' => 'iso-27001-2022', 'ref' => 'A.8.20', 'set' => ['auto_check' => ['warranty', null]], 'why' => 'Warranty status is not evidence of network security (it fits A.7.13).'],
    ['fw' => 'soc2-tsc', 'ref' => 'CC6.1', 'set' => ['title' => ['Logical access security software, infrastructure and architecture protect information assets', 'Access to protected information is controlled through identity, network and encryption safeguards']], 'why' => 'Title kept long runs of the criterion wording.'],
    ['fw' => 'soc2-tsc', 'ref' => 'CC6.3', 'set' => ['guidance' => ['Role-based groups, separate admin accounts, and periodic access reviews. Evidence: group membership exports, quarterly access review sign-off.', 'Role-based groups, separate admin accounts, conflicting duties split between people (segregation of duties), and periodic access reviews. Evidence: group membership exports, quarterly access review sign-off, a role matrix showing incompatible duties.']], 'why' => 'CC6.3 names segregation of duties as well as least privilege.'],
    ['fw' => 'soc2-tsc', 'ref' => 'CC6.6', 'set' => ['title' => ['Security measures protect against threats from outside system boundaries', 'Defenses are in place against attacks coming from outside the system']], 'why' => 'Title kept long runs of the criterion wording.'],
    ['fw' => 'nist-csf-2', 'ref' => 'ID.RA-02', 'set' => ['tags' => ['vuln_remediation', 'gov_risk_assessment,vuln_remediation']], 'why' => 'Threat intelligence feeds the risk assessment.'],
    ['fw' => 'cis-v8-ig1', 'framework' => ['name' => ['CIS Controls v8 — IG1', 'CIS Controls v8.1 — IG1'], 'description' => ['Implementation Group 1 ("essential cyber hygiene"): the 56 safeguards CIS recommends every organization implement. Titles are MSP Align\'s own summaries, not CIS text; refs are the CIS safeguard numbers. CIS Controls® is a registered trademark of the Center for Internet Security, Inc.; no affiliation or endorsement.', 'The CIS Critical Security Controls v8.1 (June 2024), Implementation Group 1 ("essential cyber hygiene"): the 56 safeguards CIS recommends as the minimum for every organization, especially small businesses with limited IT and security staff. The IG1 safeguard numbers are the same in v8 and v8.1. There is no certification. Titles are MSP Align\'s own summaries, not CIS text; refs are the CIS safeguard numbers. CIS Controls® is a registered trademark of the Center for Internet Security, Inc.; no affiliation or endorsement.']], 'why' => 'v8.1 (June 2024) replaced v8; the IG1 safeguard numbers did not change.'],
    ['fw' => 'cis-v81-ig2', 'ref' => '3.12', 'set' => ['guidance' => ['IG2. Sensitive data is not processed on systems intended for lower-sensitivity data. Evidence: network or tenant segmentation and system classification.', 'IG2. Systems that handle sensitive data are kept apart from general-purpose systems, so sensitive data stays on assets rated for it. Evidence: network or tenant segmentation and system classification.']], 'why' => '4.4: a perimeter firewall does not meet the server-firewall safeguard; 3.12/4.5: reworded from the CIS text.'],
    ['fw' => 'cis-v81-ig2', 'ref' => '4.4', 'set' => ['guidance' => ['IG1. Servers have a host firewall or sit behind a managed firewall with default-deny rules. Evidence: Windows Firewall/iptables policy export.', 'IG1. Each server runs its own firewall where the platform supports it (the built-in OS firewall, a virtual firewall or a firewall agent); a perimeter firewall alone does not count. Evidence: Windows Firewall/iptables policy export per server.']], 'why' => '4.4: a perimeter firewall does not meet the server-firewall safeguard; 3.12/4.5: reworded from the CIS text.'],
    ['fw' => 'cis-v81-ig2', 'ref' => '4.5', 'set' => ['guidance' => ['IG1. Workstations run a host firewall that drops all traffic except explicitly allowed services and ports. Evidence: host firewall policy from GPO/Intune.', 'IG1. Every workstation and laptop has its host firewall on, blocking inbound connections by default and allowing only approved ports and services. Evidence: host firewall policy from GPO/Intune.']], 'why' => '4.4: a perimeter firewall does not meet the server-firewall safeguard; 3.12/4.5: reworded from the CIS text.'],
    ['fw' => 'cis-v81-ig2', 'ref' => '2.5', 'set' => ['title' => ['Allowlist authorized software', 'Let only approved software run (application allowlisting)']], 'why' => 'Title still matched the CIS safeguard title; paraphrased (as migration 057 did for others).'],
