    ['fw' => 'cis-v8-ig1', 'ref' => '1.1', 'set' => ['section' => ['1 Inventory of Enterprise Assets', '1. Inventory and Control of Enterprise Assets'], 'guidance' => [null, 'Every end-user device, server, network device and IoT device (on-prem, remote and cloud) is recorded with owner, address and approval status, and reviewed at least twice a year. Evidence: RMM/PSA asset export and the date of the last review.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
