    ['fw' => 'cis-v8-ig1', 'ref' => '3.1', 'set' => ['section' => ['3 Data Protection', '3. Data Protection'], 'guidance' => [null, 'A documented process covers data sensitivity, owners, handling, retention and disposal, reviewed yearly. Evidence: approved data management policy or procedure.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
