    ['fw' => 'cis-v8-ig1', 'ref' => '4.3', 'set' => ['section' => ['4 Secure Configuration', '4. Secure Configuration of Enterprise Assets and Software'], 'guidance' => [null, 'Workstations lock after no more than 15 minutes idle and mobile devices after no more than 2 minutes. Evidence: GPO/Intune screen-lock settings.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
