    ['fw' => 'cis-v8-ig1', 'ref' => '6.1', 'set' => ['section' => ['6 Access Control Management', '6. Access Control Management'], 'guidance' => [null, 'Access is granted through a documented, preferably automated, process on hire or role change. Evidence: onboarding procedure and sample approved access tickets.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
