    ['fw' => 'cis-v8-ig1', 'ref' => '14.3', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Training covers MFA, password composition and credential management. Evidence: training module completion.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '14.4', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Training covers identifying, storing, transferring, archiving and destroying sensitive data, plus clear desk/screen. Evidence: training module completion.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '14.5', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Training covers misdelivery, losing devices and publishing data to the wrong audience. Evidence: training module completion.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '14.6', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Staff know the signs of a possible incident and how to report it. Evidence: training module and reporting instructions.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '14.7', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Staff can check whether their devices are updating and know to report failures to IT. Evidence: training module completion.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '14.8', 'set' => ['section' => ['14 Security Awareness and Skills Training', '14. Security Awareness and Skills Training'], 'guidance' => [null, 'Training covers public/home Wi-Fi risks and using VPN when working remotely. Evidence: training module completion.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '15.1', 'set' => ['section' => ['15 Service Provider Management', '15. Service Provider Management'], 'guidance' => [null, 'Service providers are listed with classification and an enterprise contact, reviewed yearly. Evidence: vendor inventory.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '17.1', 'set' => ['section' => ['17 Incident Response Management', '17. Incident Response Management'], 'guidance' => [null, 'A primary person and at least one backup coordinate incident handling, internal or at a provider. Evidence: named roles in the IR plan.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '17.2', 'set' => ['section' => ['17 Incident Response Management', '17. Incident Response Management'], 'guidance' => [null, 'Contacts for staff, providers, insurers, law enforcement and regulators are kept current and verified yearly. Evidence: incident contact list with review date.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'cis-v8-ig1', 'ref' => '17.3', 'set' => ['section' => ['17 Incident Response Management', '17. Incident Response Management'], 'guidance' => [null, 'A documented process tells staff how, when and to whom to report, reviewed yearly. Evidence: reporting procedure published to staff.']], 'why' => 'Official CIS Control names as sections, and guidance (frequencies and evidence) like the IG2 checklist.'],
    ['fw' => 'm365-baseline', 'framework' => ['description' => ['A secure-configuration review for client Microsoft 365 tenants: identity, email, collaboration, devices, data protection, logging and backup. Aligned with the CISA SCuBA Secure Configuration Baselines for M365 and the CIS Microsoft 365 Foundations Benchmark v7.0.0 (May 2026), and cross-checked against Microsoft Secure Score; source control IDs are cited in each item\'s guidance. Some items need Entra ID P1 (Conditional Access; included in Business Premium and E3), Entra ID P2 (Identity Protection, PIM; E5 or add-on), or Defender for Office 365 / Defender for Endpoint / Purview licensing; the guidance says which. Tenants without P1 should at least have Security Defaults on. Titles and guidance are paraphrased summaries for tracking a review, not the official benchmark text.', 'A secure-configuration review for client Microsoft 365 tenants: identity, email, collaboration, devices, data protection, logging and backup. Aligned with the CISA SCuBA Secure Configuration Baselines for M365 (ScubaGear v2.0, including the Security Suite baseline that replaced the Defender baseline) and the CIS Microsoft 365 Foundations Benchmark v7.0.0 (May 2026), and cross-checked against Microsoft Secure Score; source control IDs are cited in each item\'s guidance. Some items need Entra ID P1 (Conditional Access; included in Business Premium and E3), Entra ID P2 (Identity Protection, PIM; E5 or add-on), or Defender for Office 365 / Defender for Endpoint / Purview licensing; the guidance says which. Tenants without P1 should at least have Security Defaults on. Titles and guidance are paraphrased summaries for tracking a review, not the official benchmark text.']], 'why' => 'ScubaGear v2.0 replaced the Defender baseline with the Security Suite baseline.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-MDO-01', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.1.1v1, 1.2v1, 1.3v1. Defender for Office 365 Plan 1 is in Business Premium; Plan 2 in E5.', 'SCuBA MS.SECURITYSUITE.1.1v1-1.3v1 (malware) and 6.1v1 (spam and phishing kept out of the inbox); the Standard and Strict presets meet these. Defender for Office 365 Plan 1 is in Business Premium; Plan 2 in E5.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-MDO-02', 'set' => ['guidance' => ['CIS 2.1.1. Needs Defender for Office 365 Plan 1.', 'SCuBA MS.SECURITYSUITE.7.1v1, 7.2v1, 7.3v1 / CIS 2.1.1. Needs Defender for Office 365 Plan 1.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-MDO-03', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.3.1v1 / CIS 2.1.4, 2.1.5, 2.1.2. Needs Defender for Office 365 Plan 1 (attachment filter is in EOP).', 'SCuBA MS.SECURITYSUITE.1.1v1 (block click-to-run attachments), 1.4v1 (SharePoint, OneDrive and Teams) / CIS 2.1.4, 2.1.5, 2.1.2. Needs Defender for Office 365 Plan 1 (the attachment filter is in EOP).']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-MDO-04', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.2.1v1, 2.2v1, 2.3v1 / CIS 2.1.7. Needs Defender for Office 365 Plan 1.', 'SCuBA MS.SECURITYSUITE.2.1v1, 2.2v1, 2.3v1, 2.4v1 (safety tips) / CIS 2.1.7. Needs Defender for Office 365 Plan 1.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-MDO-05', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.1.4v1, 1.5v1 / CIS 2.4.1, 2.4.2.', 'SCuBA MS.SECURITYSUITE.2.1v1 (impersonation protection for sensitive accounts) / CIS 2.4.1, 2.4.2.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-DP-02', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.4.1v2, 4.2v1 / CIS 3.2.1, 3.2.2. Start in test mode with policy tips, then enforce.', 'SCuBA MS.SECURITYSUITE.3.1v1-3.5v1 / CIS 3.2.1, 3.2.2. Start in test mode with policy tips, then enforce.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-LOG-01', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.6.1v1 / CIS 3.1.1. Evidence: Get-AdminAuditLogConfig showing UnifiedAuditLogIngestionEnabled = True.', 'SCuBA MS.SECURITYSUITE.5.1v1 / CIS 3.1.1. Evidence: Get-AdminAuditLogConfig showing UnifiedAuditLogIngestionEnabled = True.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-LOG-02', 'set' => ['guidance' => ['SCuBA MS.DEFENDER.5.1v1, 5.2v1; MS.AAD.4.1v1 (Entra logs to the SOC). Include alerts for new inbox forwarding rules, mass downloads and admin role changes.', 'SCuBA MS.SECURITYSUITE.4.1v1, 4.2v1; MS.AAD.4.1v1 (Entra logs to the SOC). Include alerts for new inbox forwarding rules, mass downloads and admin role changes.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-LOG-03', 'set' => ['title' => ['Audit logs retained long enough for investigations (default 180 days on Audit Standard; exported to a SIEM or archive for longer retention)', 'Audit logs searchable for at least 3 months and retrievable for 12 months (default 180 days on Audit Standard; longer through Audit Premium or export to a SIEM or archive)'], 'guidance' => ['SCuBA MS.DEFENDER.6.3v1. One-year retention needs Audit Premium (E5) or export. Evidence: retention policy or SIEM ingestion.', 'SCuBA MS.SECURITYSUITE.5.2v1. One-year retention needs Audit Premium (E5) or export. Evidence: audit retention policy or SIEM ingestion.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them. The baseline asks for 3 months searchable and 12 months retrievable.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-EXO-09', 'set' => ['guidance' => ['CIS 6.2.2, 2.1.12, 2.1.13, 2.1.14. Evidence: export of transport rules and anti-spam policies.', 'CIS 6.2.2, 2.1.12, 2.1.13, 2.1.14. Evidence: export of transport rules and anti-spam policies. SCuBA MS.SECURITYSUITE.6.2v1, 8.1v1, 8.2v1.']], 'why' => 'MS.DEFENDER IDs were retired in ScubaGear v2.0; the Security Suite baseline (MS.SECURITYSUITE) replaced them.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-EXO-04', 'set' => ['guidance' => ['SCuBA MS.EXO.5.1v1 / CIS 6.5.4. Move scanners and apps to a relay connector or Graph.', 'SCuBA MS.EXO.5.1v1 / CIS 6.5.4. Move scanners and apps to a relay connector, OAuth SMTP or Graph: Microsoft is retiring Basic authentication for SMTP AUTH, so devices that send with a password must move anyway.']], 'why' => 'Basic authentication for SMTP AUTH is being retired.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-EXO-07', 'set' => ['guidance' => ['SCuBA MS.EXO.13.1v1 / CIS 6.1.1, 6.1.2.', 'SCuBA MS.EXO.13.1v1 / CIS 6.1.1, 6.1.2, 6.1.3 (no mailbox has AuditBypassEnabled).']], 'why' => '"Not bypassed" is CIS 6.1.3.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-ID-03', 'set' => ['title' => ['Weak authentication methods (SMS, voice call, email OTP) disabled and Microsoft Authenticator shows number matching and sign-in context', 'Weak authentication methods (SMS, voice call, email OTP) disabled and Microsoft Authenticator shows sign-in context (app name and location); number matching is always on']], 'why' => 'Number matching is always on; the baseline (MS.AAD.3.3v2) asks for sign-in context.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-ID-10', 'set' => ['guidance' => ['SCuBA MS.AAD.7.4v1, 7.5v1, 7.6v1, 7.7v1, 7.8v1; CIS also recommends PIM (Level 2). Needs Entra ID P2 (E5 or add-on); mark N/A with reason if unlicensed.', 'SCuBA MS.AAD.7.4v1-7.9v1 (7.9: alert when other highly privileged roles are activated); CIS also recommends PIM (Level 2). Needs Entra ID P2 (E5 or add-on) or a third-party PAM tool; mark N/A with reason if neither.']], 'why' => 'MS.AAD.7.9v1 added.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-ID-11', 'set' => ['title' => ['Two break-glass (emergency access) accounts exist, are cloud-only, excluded from Conditional Access, protected with FIDO2 or long stored secrets, and their sign-ins trigger alerts', 'Two break-glass (emergency access) accounts exist, are cloud-only, excluded from Conditional Access, protected with phishing-resistant MFA (FIDO2 passkey or certificate), and their sign-ins trigger alerts'], 'guidance' => ['CIS 1.1.2. Evidence: account names, where credentials are stored, alert rule, and last test date.', 'CIS 1.1.2. Evidence: account names, where credentials are stored, alert rule, and last test date. Microsoft enforces MFA for the Azure portal and the Entra and Intune admin centers, so password-only break-glass accounts can no longer sign in to admin tools.']], 'why' => 'Microsoft requires MFA for its admin portals, so a password-only emergency account cannot sign in to them.'],
    ['fw' => 'm365-baseline', 'insert' => ['Identity (Entra ID)', 'M365-ID-19', 'App registrations cannot add client secrets (passwords); where secrets are still allowed they expire within 180 days, and certificates within 365 days', 'SCuBA MS.AAD.5.5v1, 5.6v1, 5.7v1 (Entra application management policies). Evidence: tenant app management policy export and a list of app credentials with expiry dates.', null, 'cloud_config,iam_passwords'], 'after' => 'M365-ID-18', 'why' => 'MS.AAD.5.5v1-5.7v1 (application credential policies) had no item.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-TMS-03', 'set' => ['title' => ['Guest access to Teams and Microsoft 365 Groups is governed: guest settings reviewed and third-party/custom Teams apps require approval', 'Teams apps (Microsoft, third-party and custom) install only when approved, and Teams and Microsoft 365 Groups guest settings are reviewed']], 'why' => 'MS.TEAMS.5.1-5.3 cover app approval; the title led with guest access.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-DEV-03', 'set' => ['auto_check' => ['stale', null]], 'why' => 'RMM check-ins say nothing about Defender onboarding or tamper protection.'],
    ['fw' => 'm365-baseline', 'ref' => 'M365-BAK-01', 'set' => ['title' => ['Third-party backup protects Exchange, OneDrive, SharePoint and Teams data daily', 'A backup service (third-party, or Microsoft 365 Backup) protects Exchange, OneDrive, SharePoint and Teams data daily'], 'guidance' => ['Microsoft\'s shared responsibility model does not include point-in-time backup of customer data; recycle bins and retention are not backups. Evidence: backup job report covering all licensed users and sites.', 'Point-in-time backup is not included in Microsoft 365 licences (Microsoft 365 Backup is a separate paid service that keeps copies inside Microsoft\'s cloud; a third-party copy also gives separation). Recycle bins and retention are not backups. Evidence: backup job report covering all licensed users and sites.']], 'why' => 'Microsoft 365 Backup (a paid Microsoft service) exists since 2024.'],
    ['fw' => 'cyber-insurance', 'ref' => 'CI-7', 'set' => ['auto_check' => ['huntress_agents', null]], 'why' => 'Agent coverage does not show 24/7 monitoring.'],
    ['fw' => 'cyber-insurance', 'insert' => ['Backups', 'CI-20', 'Backup consoles and storage use separate credentials protected by MFA', 'Commonly asked on ransomware supplements: backup admin accounts are not domain accounts, have MFA, and cannot delete immutable copies.', null, 'iam_mfa_admin,data_backup_offsite'], 'after' => 'CI-11', 'why' => 'Near-universal question on ransomware supplements.'],
    ['fw' => 'msp-baseline', 'insert' => ['Identity', 'MSB-27', 'MFA required for all administrator and MSP tool accounts (RMM, PSA, backup, firewall, Microsoft 365 admin)', null, 'm365_mfa_admins', 'iam_mfa_admin,iam_privileged'], 'after' => 'MSB-26', 'why' => 'The insurance list asks for it; the MSP baseline did not.'],
    ['fw' => 'msp-baseline', 'insert' => ['People & process', 'MSB-28', 'Security alerts from EDR, Microsoft 365 and firewalls are monitored, with a defined response time', null, null, 'log_review,ep_edr'], 'after' => 'MSB-27', 'why' => 'The insurance list asks for it; the MSP baseline did not.'],
